steps.css:
body {
  max-width: 380px;
  margin: 30px auto;
  padding: 24px;
  font-family: Arial, sans-serif;
  text-align: center;
  color: #253947;
  background: #f1f8f6;
  border: 2px solid #bbd9ce;
  border-radius: 18px;
}
h1 { color: #265b50; }
.brett {
  display: grid;
  grid-template-columns: repeat(3, 70px);
  justify-content: center;
  gap: 7px;
  margin: 18px auto;
}
.feld {
  width: 70px;
  height: 70px;
  border: 2px solid #a9c9bd;
  border-radius: 8px;
  background: white;
  color: #285b50;
  font-size: 2rem;
  font-weight: bold;
  cursor: pointer;
}
.feld:hover { background: #e4f4ed; }
button.neustart {
  padding: 10px 15px;
  color: white;
  background: #367866;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}
#meldung { min-height: 1.5em; font-weight: bold; }

